// Get the record ID from the automation input
let config = input.config();
let recordId = config.recordId;

// Reference the hardcoded table and field names
let table = base.getTable("Onboarding");
let inputFieldName = "Website Link";
let outputFieldName = "Suggested Domains";

// Fetch the specific record
let record = await table.selectRecordAsync(recordId);
if (!record) {
    throw new Error(`No record found for ID: ${recordId}`);
}

let website = record.getCellValueAsString(inputFieldName);
if (!website) return;

// --- Parse domain ---
let cleaned = website.replace("https://", "").replace("http://", "").replace("www.", "");
let parts = cleaned.split(".");
if (parts.length < 2) return;

let ltd = "." + parts.pop();
let root = parts.join('');

// --- Generate domain suggestions ---
let prefixes = ['use', 'try', 'have', 'boost', 'get', 'send', 'go', 'start', 'grow', 'hey', 'explore', 'leverage', 'scale', 'growth', 'grow'];
let suffixes = ['boost', 'outbound', 'pro', 'hub', 'team', 'leverage', 'connect', 'solutions', 'scale', 'growth', 'grow'];
let domains = new Set();

prefixes.forEach(p => domains.add(`${p}${root}.com`));
suffixes.forEach(s => domains.add(`${root}${s}.com`));

while (domains.size < 50) {
    let p = prefixes[Math.floor(Math.random() * prefixes.length)];
    let s = suffixes[Math.floor(Math.random() * suffixes.length)];
    domains.add(`${p}${root}${s}.com`);
}

let finalOutput = Array.from(domains).slice(0, 50).join('\n');

// --- Update record ---
await table.updateRecordAsync(record.id, {
    [outputFieldName]: finalOutput
});

// Get the inputs from automation config
let config = input.config();
let recordId = config.recordId;
let names = config.names || "";
let companyName = config.company_name || "";

// Reference table and fields
let table = base.getTable("Onboarding");
let emailPatternField = "ci_user_name_email_pattern";
let passwordField = "ci_password";

// Fetch the record
let record = await table.selectRecordAsync(recordId);
if (!record) throw new Error(`No record found for ID: ${recordId}`);

// --- Generate Email Patterns ---
let emailPatterns = [];
let nameList = names.split(",").map(n => n.trim()).filter(Boolean);

for (let fullName of nameList) {
    let [first, ...rest] = fullName.toLowerCase().split(" ");
    let last = rest.join(".");
    if (first) {
        emailPatterns.push(`${first}@`);
        if (last) emailPatterns.push(`${first}.${last}@`);
    }
}
let finalEmailPatterns = emailPatterns.join(", ");

// --- Generate Password ---
let noSpaces = companyName.replace(/\s+/g, "");
let camelCase = noSpaces.charAt(0).toUpperCase() + noSpaces.slice(1);
let password = camelCase + "99$$";

// --- Update the record ---
await table.updateRecordAsync(record.id, {
    [emailPatternField]: finalEmailPatterns,
    [passwordField]: password
});

let table = base.getTable("Onboarding");
let recordId = input.config().recordId;
let record = await table.selectRecordAsync(recordId);
let webhook = "https://n8n.dulcy.io/webhook/REDACTED_PATH";

let payload = { recordId };

for (let field of table.fields) {
    payload[field.name] = record.getCellValue(field.name);
}

await fetch(webhook, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload)
});
